using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [Serializable]public class R17MaterialRow{public string target,material,fixture;public float threshold,mass,retention;public List<Bounds> shapes=new List<Bounds>();public List<BreakRecord> events=new List<BreakRecord>();}
 [Serializable]public class R17MaterialReport{public string method="Two deliberately positioned actual collision fixtures, not natural reach. Same geometry/mass/threshold/retention; visual material role only.";public List<R17MaterialRow> rows=new List<R17MaterialRow>();}
 [UnityTest]public IEnumerator R17Materials(){Directory.CreateDirectory(Evidence);var file=Path.Combine(Evidence,"material-probe.json");Assert.That(File.Exists(file),Is.False);var report=new R17MaterialReport();foreach(string target in new[]{"street3-+1-04-market_stall","street3-+1-02-crate_stack"}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(12,0,2);var sim=Property(current,"ReviewSimulation");object panel=null;foreach(var p in (IEnumerable)Field(sim,"panels"))if((string)Field(p,"id")==target)panel=p;Assert.That(panel,Is.Not.Null);var row=new R17MaterialRow{target=target,material=(string)Field(panel,"type"),threshold=F(panel,"threshold"),retention=F(panel,"retention"),mass=F(Field(panel,"cityProposal"),"massKgSuggestion")};foreach(Collider c in (IEnumerable)Field(panel,"shapes"))row.shapes.Add(c.bounds);report.rows.Add(row);row.fixture=(string)Call(sim,"ReviewRouteSegmentR11",target);float x=((Vector3)Field(panel,"position")).x;CaptureSectorR11(target+"-before",x,5.5f,8f);bool hit=false;for(int i=0;i<120&&!hit;i++){Call(current,"Tick",1f/60);foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))if((string)Field(e,"id")==target)hit=true;}for(int i=0;i<8;i++)Call(current,"Tick",1f/60);foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.events.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});CaptureSectorR11(target+"-after",x,5.5f,8f);File.WriteAllText(file,JsonUtility.ToJson(report,true));Assert.That(hit,Is.True,"actual fixture target");Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}}
}
#endif
